<?php
declare(strict_types=1);require_once __DIR__.'/config/lead_step20.php';$error=null;$success=null;$rows=[];try{$pdo=business_db();$user=security_step17_current_user($pdo);$ctx=lead_step20_context($pdo);$orgId=(int)$ctx['organization_id'];if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){security_step17_verify_csrf((string)($_POST['csrf']??''));lead_step20_appointment_status($pdo,$orgId,(int)($_POST['appointment_id']??0),(string)($_POST['status']??'scheduled'),(int)$user['id'],(string)($_POST['notes']??''));$success='Appointment status updated.';}$s=$pdo->prepare("SELECT a.*,l.lead_code,l.full_name,l.mobile,u.full_name assigned_name FROM crm_appointments a JOIN crm_leads l ON l.id=a.lead_id AND l.organization_id=a.organization_id LEFT JOIN system_users u ON u.id=a.assigned_user_id WHERE a.organization_id=? ORDER BY a.start_at>=NOW() DESC,a.start_at ASC LIMIT 500");$s->execute([$orgId]);$rows=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Lead Appointments</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/step10.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="lead_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>STEP 20 • Appointment Calendar</small></span></a><div class="os-top-actions"><a class="os-btn" href="lead_followups.php">Follow-ups</a><a class="os-btn primary" href="lead_center.php">Leads</a></div></div></header><main class="os-main" style="max-width:1450px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">APPOINTMENT PIPELINE</div><h1>Requested appointments become confirmed internal schedules only after review.</h1><p>Website visitors can request a preferred time. Staff confirms the real appointment in Lead 360°.</p></section><?php if($error):?><div class="pp-alert bad"><?= lead_step20_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><?= lead_step20_h($success) ?></div><?php endif;?><section class="os-card"><div class="s10-list"><?php if(!$rows):?><div class="pp-alert">No confirmed appointments yet.</div><?php endif;?><?php foreach($rows as $r):?><div class="s10-row"><div><b><?= lead_step20_h($r['appointment_code'].' • '.$r['full_name']) ?></b><small><a href="lead_detail.php?id=<?= (int)$r['lead_id'] ?>"><?= lead_step20_h($r['lead_code']) ?></a> • <?= lead_step20_h($r['start_at'].' • '.strtoupper($r['appointment_mode'])) ?><?= $r['assigned_name']?' • '.lead_step20_h($r['assigned_name']):'' ?></small><?php if($r['purpose']):?><small><?= lead_step20_h($r['purpose']) ?></small><?php endif;?></div><form method="post" style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input type="hidden" name="csrf" value="<?= lead_step20_h(security_step17_csrf()) ?>"><input type="hidden" name="appointment_id" value="<?= (int)$r['id'] ?>"><select name="status"><?php foreach(['scheduled','completed','cancelled','no_show','rescheduled'] as $st):?><option value="<?= $st ?>" <?= $r['status']===$st?'selected':'' ?>><?= ucwords(str_replace('_',' ',$st)) ?></option><?php endforeach;?></select><input name="notes" placeholder="optional note"><button class="os-btn">Update</button></form></div><?php endforeach;?></div></section></main></body></html>